import React, { useState } from 'react';
import './App.css';
import problems from './problems.js';

function App() {
  const [minRating, setMinRating] = useState('');
  const [maxRating, setMaxRating] = useState('');
  const [minContest, setMinContest] = useState('');
  const [result, setResult] = useState(null);

  const getProblem = () => {
    const minContestNum = parseInt(minContest, 10);
    const minRatingNum = parseInt(minRating, 10);
    const maxRatingNum = parseInt(maxRating, 10);

    let filteredProblems = problems;

    if (!isNaN(minContestNum)) {
      filteredProblems = filteredProblems.filter(problem => problem.contestId >= minContestNum);
    }

    if (!isNaN(minRatingNum)) {
      filteredProblems = filteredProblems.filter(problem => problem.rating >= minRatingNum);
    }

    if (!isNaN(maxRatingNum)) {
      filteredProblems = filteredProblems.filter(problem => problem.rating <= maxRatingNum);
    }

    if (filteredProblems.length === 0) {
      setResult("No problems found with the given filters.");
      return;
    }

    const randomProblem = filteredProblems[Math.floor(Math.random() * filteredProblems.length)];
    setResult(randomProblem);
  };

  return (
    <div className="page-wrapper">
      <h1 className="title">CF Problem Picker</h1>
  
      <div className="form-container">
        <input
          id="minContest"
          type="number"
          className="input-field"
          placeholder="Enter minimum contest ID"
          value={minContest}
          onChange={e => setMinContest(e.target.value)}
        />
  
        <input
          id="minRating"
          type="number"
          className="input-field"
          placeholder="Enter minimum rating"
          value={minRating}
          onChange={e => setMinRating(e.target.value)}
        />
  
        <input
          id="maxRating"
          type="number"
          className="input-field"
          placeholder="Enter maximum rating"
          value={maxRating}
          onChange={e => setMaxRating(e.target.value)}
        />
  
        <button className="button" onClick={getProblem}>Randomize</button>
  
        {result && (
          <a
            href={`https://codeforces.com/problemset/problem/${result.contestId}/${result.index}`}
            target="_blank"
            rel="noopener noreferrer"
            className="problem-card"
          >
            <div className="problem-code">{result.contestId}{result.index}</div>
            <div className="problem-name">{result.name}</div>
            <div className="problem-rating">{result.rating}</div>
          </a>
        )}
      </div>
    </div>
  );
}

export default App;
